files.src/discount.ts:
export function applyDiscount(total: number, eligible: boolean) {
  return eligible ? total * 0.9 : total;
}

files.src/expiry.ts:
export function rejectExpiredPromotion(expiresAt: number, now: number) {
  return expiresAt < now;
}

files.src/receipt.ts:
export function sendOrderReceipt(orderId: string) {
  return { orderId, sent: true };
}

files.src/stock.ts:
export function reduceProductStock(stock: number, quantity: number) {
  return stock - quantity;
}

files.src/email.ts:
export function normalizeEmail(address: string) {
  return address.trim().toLowerCase();
}

files.src/retry.ts:
export function limitRetryAttempts(attempts: number, maximum: number) {
  return attempts < maximum;
}

files.src/shipping.ts:
export function calculateShippingCost(weight: number, rate: number) {
  return weight * rate;
}

files.src/pagination.ts:
export function paginateSearchResults(results: string[], offset: number, limit: number) {
  return results.slice(offset, offset + limit);
}

files.src/refund.ts:
export function refundPaymentAmount(requested: number, paid: number) {
  return Math.min(requested, paid);
}

files.src/currency.ts:
export function formatCurrencyAmount(amount: number) {
  return amount.toFixed(2);
}
